-- Salon and Parlour Booking Platform: core database schema (PostgreSQL 15+, Supabase)
--
-- Draft for review. Not yet run against a real PostgreSQL.
--
-- Rules (same as docs/api-conventions.md):
--   * ids are UUID, generated by the database
--   * times are timestamptz (UTC); opening hours and breaks are local shop time (time)
--   * money is integer poisha in columns ending _poisha (100 poisha = 1 taka)
--   * snake_case names; the names match the frontend fixtures in
--     frontend/src/mocks/shops.ts and frontend/src/mocks/bookings.ts
--   * status and type columns are text with CHECK, not enum types, so a new value
--     is a small migration
--
-- Auth is Supabase Auth (decided 24 November 2026). Passwords and OTP codes live in
-- auth.users, so there is no users table and no otp_codes table here. public.profiles
-- holds the name, phone and role. Its real definition is the migration
-- supabase/migrations/20261124040000_create_profiles.sql; the block below must match it.
--
-- Fields that the frontend shows but the database does not store (the API computes them):
--   customer_name, service_name (joined), position and estimated_wait_minutes of a
--   queue entry (worked out from the queue), image_urls of a service (joined from
--   service_images).

create extension if not exists btree_gist;


-- ---------------------------------------------------------------------------
-- Accounts
-- ---------------------------------------------------------------------------

-- Mirror of supabase/migrations/20261124040000_create_profiles.sql (checked against it).
-- The migration also holds the RLS policy and the signup trigger; they are not repeated here.
-- Email lives in auth.users. preferred_language (C-07) is added by its own migration,
-- supabase/migrations/20261127100000_add_profile_language.sql; null = not chosen yet.
create table if not exists public.profiles (
  id         uuid primary key references auth.users (id) on delete cascade,
  full_name  text not null,
  phone      text,
  role       text not null default 'customer'
               check (role in ('customer', 'owner', 'staff', 'admin')),
  created_at timestamptz not null default now(),
  preferred_language text check (preferred_language in ('bn', 'en'))
);


-- ---------------------------------------------------------------------------
-- Plans (FR-10.3)
-- ---------------------------------------------------------------------------

create table commission_plans (
  id                 uuid primary key default gen_random_uuid(),
  name               text not null unique,
  plan_type          text not null check (plan_type in ('commission', 'subscription')),
  commission_percent numeric(5, 2) check (commission_percent between 0 and 100),
  monthly_fee_poisha integer check (monthly_fee_poisha >= 0),
  is_active          boolean not null default true,
  created_at         timestamptz not null default now(),
  constraint commission_plans_value check (
    (plan_type = 'commission' and commission_percent is not null)
    or (plan_type = 'subscription' and monthly_fee_poisha is not null)
  )
);


-- ---------------------------------------------------------------------------
-- Shops (FR-01.1, FR-01.4, FR-10.1)
-- ---------------------------------------------------------------------------

create table shops (
  id                        uuid primary key default gen_random_uuid(),
  owner_id                  uuid not null references profiles (id),
  commission_plan_id        uuid references commission_plans (id),
  name                      text not null,
  description               text not null default '',
  address                   text not null default '',
  area                      text not null default '',
  city                      text not null default 'Dhaka',
  latitude                  numeric(9, 6) check (latitude between -90 and 90),
  longitude                 numeric(9, 6) check (longitude between -180 and 180),
  phone                     text,
  gender_category           text not null default 'unisex'
                              check (gender_category in ('men', 'women', 'unisex')),
  -- 'draft' = not submitted yet. approval_reason is shown when rejected or suspended.
  status                    text not null default 'draft'
                              check (status in ('draft', 'pending', 'approved', 'rejected', 'suspended')),
  approval_reason           text,
  -- Per-shop booking settings (open decision 2(d); defaults are proposals).
  requires_booking_approval boolean not null default false,
  allowed_payment_modes     text[] not null default array['pay_at_shop']
                              check (
                                cardinality(allowed_payment_modes) >= 1
                                and allowed_payment_modes <@ array['deposit', 'full', 'pay_at_shop']::text[]
                              ),
  deposit_percent           smallint not null default 30 check (deposit_percent between 1 and 100),
  cancellation_window_hours smallint not null default 4 check (cancellation_window_hours >= 0),
  confirmation_lead_hours   smallint not null default 2 check (confirmation_lead_hours > 0),
  cover_image_url           text,
  tour_url                  text,
  -- Kept up to date by the backend when a review is added, so shop lists stay fast.
  rating_average            numeric(2, 1) not null default 0 check (rating_average between 0 and 5),
  review_count              integer not null default 0 check (review_count >= 0),
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now()
);

create index shops_owner_idx on shops (owner_id);
create index shops_status_idx on shops (status);

-- day_of_week: 0 = Sunday ... 6 = Saturday. Times are local shop time.
create table shop_working_hours (
  shop_id     uuid not null references shops (id) on delete cascade,
  day_of_week smallint not null check (day_of_week between 0 and 6),
  opens_at    time not null,
  closes_at   time not null,
  is_closed   boolean not null default false,
  primary key (shop_id, day_of_week),
  check (is_closed or opens_at < closes_at)
);

create table shop_documents (
  id          uuid primary key default gen_random_uuid(),
  shop_id     uuid not null references shops (id) on delete cascade,
  doc_type    text not null check (doc_type in ('trade_licence', 'other')),
  file_name   text not null,
  file_url    text not null,
  uploaded_at timestamptz not null default now()
);

create index shop_documents_shop_idx on shop_documents (shop_id);

create table shop_images (
  id         uuid primary key default gen_random_uuid(),
  shop_id    uuid not null references shops (id) on delete cascade,
  url        text not null,
  alt_text   text not null default '',
  sort_order integer not null default 0
);

create index shop_images_shop_idx on shop_images (shop_id, sort_order);


-- ---------------------------------------------------------------------------
-- Services and offers (FR-01.2, FR-01.3)
-- ---------------------------------------------------------------------------

create table services (
  id               uuid primary key default gen_random_uuid(),
  shop_id          uuid not null references shops (id) on delete cascade,
  name             text not null,
  price_poisha     integer not null check (price_poisha > 0),
  duration_minutes smallint not null check (duration_minutes between 5 and 480),
  gender_category  text not null default 'unisex'
                     check (gender_category in ('men', 'women', 'unisex')),
  is_active        boolean not null default true,
  created_at       timestamptz not null default now()
);

create index services_shop_idx on services (shop_id);

create table service_images (
  id         uuid primary key default gen_random_uuid(),
  service_id uuid not null references services (id) on delete cascade,
  url        text not null,
  sort_order integer not null default 0
);

create index service_images_service_idx on service_images (service_id, sort_order);

create table offers (
  id               uuid primary key default gen_random_uuid(),
  shop_id          uuid not null references shops (id) on delete cascade,
  title            text not null,
  offer_type       text not null check (offer_type in ('percentage', 'fixed', 'combo')),
  discount_percent smallint,
  discount_poisha  integer,
  starts_at        timestamptz not null,
  ends_at          timestamptz not null,
  is_active        boolean not null default true,
  created_at       timestamptz not null default now(),
  check (ends_at > starts_at),
  check (
    (offer_type = 'percentage'
       and discount_percent between 1 and 90 and discount_poisha is null)
    or (offer_type in ('fixed', 'combo')
       and discount_poisha > 0 and discount_percent is null)
  )
);

create index offers_shop_idx on offers (shop_id, starts_at, ends_at);

create table offer_services (
  offer_id   uuid not null references offers (id) on delete cascade,
  service_id uuid not null references services (id) on delete cascade,
  primary key (offer_id, service_id)
);


-- ---------------------------------------------------------------------------
-- Staff and availability (FR-01.5)
-- ---------------------------------------------------------------------------

-- user_id is null until the staff member has a login (created by the shop owner).
-- email is added for Supabase Auth login (the frontend staff form has no email yet).
create table staff (
  id         uuid primary key default gen_random_uuid(),
  shop_id    uuid not null references shops (id) on delete cascade,
  user_id    uuid unique references profiles (id) on delete set null,
  full_name  text not null,
  phone      text not null,
  email      text,
  role_title text not null default '',
  is_active  boolean not null default true,
  created_at timestamptz not null default now(),
  unique (shop_id, phone)
);

create index staff_shop_idx on staff (shop_id);

create table staff_services (
  staff_id   uuid not null references staff (id) on delete cascade,
  service_id uuid not null references services (id) on delete cascade,
  primary key (staff_id, service_id)
);

create table staff_hours (
  staff_id    uuid not null references staff (id) on delete cascade,
  day_of_week smallint not null check (day_of_week between 0 and 6),
  opens_at    time not null,
  closes_at   time not null,
  is_closed   boolean not null default false,
  primary key (staff_id, day_of_week),
  check (is_closed or opens_at < closes_at)
);

-- day_of_week null = every working day.
create table staff_breaks (
  id          uuid primary key default gen_random_uuid(),
  staff_id    uuid not null references staff (id) on delete cascade,
  day_of_week smallint check (day_of_week between 0 and 6),
  starts_at   time not null,
  ends_at     time not null,
  label       text not null,
  check (starts_at < ends_at)
);

create index staff_breaks_staff_idx on staff_breaks (staff_id);

-- Holiday or emergency block.
create table staff_time_off (
  id         uuid primary key default gen_random_uuid(),
  staff_id   uuid not null references staff (id) on delete cascade,
  starts_at  timestamptz not null,
  ends_at    timestamptz not null,
  reason     text not null,
  check (ends_at > starts_at)
);

create index staff_time_off_staff_idx on staff_time_off (staff_id, starts_at);


-- ---------------------------------------------------------------------------
-- Bookings (FR-03, FR-04, FR-05)
-- ---------------------------------------------------------------------------

-- One staff member per booking. When the customer picks "anyone available" the
-- backend chooses one before the insert (decision 2(b)), so staff_id is required.
-- hold_expires_at is set only while the booking waits for its online payment.
-- Expired holds are cancelled in the same transaction before a new booking is
-- inserted (decision 2(c)); the exclusion constraint only sees active statuses.
-- payment_method and payment_status copy the latest payment, for fast lists.
create table bookings (
  id                        uuid primary key default gen_random_uuid(),
  shop_id                   uuid not null references shops (id),
  customer_id               uuid not null references profiles (id),
  staff_id                  uuid not null references staff (id),
  offer_id                  uuid references offers (id) on delete set null,
  starts_at                 timestamptz not null,
  ends_at                   timestamptz not null,
  status                    text not null default 'pending'
                              check (status in ('pending', 'confirmed', 'arrived', 'in_service',
                                                'completed', 'cancelled', 'no_show')),
  subtotal_poisha           integer not null check (subtotal_poisha >= 0),
  discount_poisha           integer not null default 0 check (discount_poisha >= 0),
  total_poisha              integer not null check (total_poisha >= 0),
  paid_poisha               integer not null default 0 check (paid_poisha >= 0),
  payment_method            text not null
                              check (payment_method in ('bkash', 'nagad', 'card', 'pay_at_shop')),
  payment_status            text not null default 'pending'
                              check (payment_status in ('pending', 'paid', 'failed', 'refunded')),
  hold_expires_at           timestamptz,
  confirmation_requested_at timestamptz,
  customer_confirmed_at     timestamptz,
  cancelled_by              text check (cancelled_by in ('customer', 'shop')),
  cancel_reason             text,
  created_at                timestamptz not null default now(),
  check (ends_at > starts_at),
  check (total_poisha = subtotal_poisha - discount_poisha),
  check (paid_poisha <= total_poisha),
  check (cancelled_by is null or status = 'cancelled'),
  -- The database itself rejects two active bookings for the same staff member
  -- at overlapping times (FR-03.3).
  constraint bookings_no_double_booking exclude using gist (
    staff_id with =,
    tstzrange(starts_at, ends_at) with &&
  ) where (status in ('pending', 'confirmed', 'arrived', 'in_service'))
);

create index bookings_shop_start_idx on bookings (shop_id, starts_at);
create index bookings_customer_start_idx on bookings (customer_id, starts_at desc);
create index bookings_staff_start_idx on bookings (staff_id, starts_at);
create index bookings_hold_idx on bookings (hold_expires_at) where hold_expires_at is not null;

-- Price and duration are copied when the booking is made, so later price changes
-- do not change old bookings.
create table booking_items (
  id               uuid primary key default gen_random_uuid(),
  booking_id       uuid not null references bookings (id) on delete cascade,
  service_id       uuid not null references services (id),
  price_poisha     integer not null check (price_poisha >= 0),
  duration_minutes smallint not null check (duration_minutes > 0)
);

create index booking_items_booking_idx on booking_items (booking_id);


-- ---------------------------------------------------------------------------
-- Payments and refunds (FR-07)
-- ---------------------------------------------------------------------------

create table payments (
  id              uuid primary key default gen_random_uuid(),
  booking_id      uuid not null references bookings (id),
  method          text not null check (method in ('bkash', 'nagad', 'card', 'pay_at_shop')),
  status          text not null default 'pending'
                    check (status in ('pending', 'paid', 'failed', 'refunded')),
  amount_poisha   integer not null check (amount_poisha >= 0),
  -- Total of the refunds table for this payment, updated in the same transaction.
  refunded_poisha integer not null default 0 check (refunded_poisha >= 0),
  transaction_ref text,
  paid_at         timestamptz,
  created_at      timestamptz not null default now(),
  check (refunded_poisha <= amount_poisha)
);

create index payments_booking_idx on payments (booking_id);
create unique index payments_transaction_ref_idx on payments (transaction_ref)
  where transaction_ref is not null;

create table refunds (
  id            uuid primary key default gen_random_uuid(),
  payment_id    uuid not null references payments (id),
  booking_id    uuid not null references bookings (id),
  amount_poisha integer not null check (amount_poisha > 0),
  reason        text,
  status        text not null default 'pending'
                  check (status in ('pending', 'processed', 'failed')),
  created_by    uuid references profiles (id) on delete set null,
  processed_at  timestamptz,
  created_at    timestamptz not null default now()
);

create index refunds_payment_idx on refunds (payment_id);


-- ---------------------------------------------------------------------------
-- Live queue (FR-06)
-- ---------------------------------------------------------------------------

-- A walk-in has no booking and no account. position and estimated_wait_minutes
-- are not stored; the API works them out from the waiting entries (FR-06.2).
create table queue_entries (
  id            uuid primary key default gen_random_uuid(),
  shop_id       uuid not null references shops (id) on delete cascade,
  booking_id    uuid unique references bookings (id) on delete set null,
  customer_id   uuid references profiles (id) on delete set null,
  customer_name text not null,
  staff_id      uuid references staff (id) on delete set null,
  status        text not null default 'waiting'
                  check (status in ('waiting', 'in_service', 'completed', 'cancelled')),
  is_walk_in    boolean not null default false,
  joined_at     timestamptz not null default now(),
  started_at    timestamptz,
  finished_at   timestamptz,
  check (is_walk_in = (booking_id is null))
);

create index queue_entries_shop_status_idx on queue_entries (shop_id, status, joined_at);

create table queue_entry_services (
  queue_entry_id uuid not null references queue_entries (id) on delete cascade,
  service_id     uuid not null references services (id),
  primary key (queue_entry_id, service_id)
);


-- ---------------------------------------------------------------------------
-- Reviews and moderation (FR-08, FR-10.2)
-- ---------------------------------------------------------------------------

create table reviews (
  id               uuid primary key default gen_random_uuid(),
  shop_id          uuid not null references shops (id) on delete cascade,
  booking_id       uuid not null unique references bookings (id),
  customer_id      uuid not null references profiles (id),
  rating           smallint not null check (rating between 1 and 5),
  comment          text not null default '',
  owner_reply      text check (char_length(owner_reply) between 1 and 500),
  owner_replied_at timestamptz,
  is_hidden        boolean not null default false,
  created_at       timestamptz not null default now(),
  check ((owner_reply is null) = (owner_replied_at is null))
);

create index reviews_shop_idx on reviews (shop_id, created_at desc);

create table review_reports (
  id          uuid primary key default gen_random_uuid(),
  review_id   uuid not null references reviews (id) on delete cascade,
  reported_by uuid not null references profiles (id),
  reason      text not null,
  status      text not null default 'open'
                check (status in ('open', 'dismissed', 'review_hidden')),
  handled_by  uuid references profiles (id) on delete set null,
  handled_at  timestamptz,
  created_at  timestamptz not null default now()
);

create index review_reports_status_idx on review_reports (status, created_at);

create table complaints (
  id             uuid primary key default gen_random_uuid(),
  booking_id     uuid not null references bookings (id),
  customer_id    uuid not null references profiles (id),
  complaint_type text not null check (complaint_type in ('dispute', 'refund')),
  description    text not null,
  status         text not null default 'open'
                   check (status in ('open', 'in_review', 'resolved', 'rejected')),
  resolution     text,
  handled_by     uuid references profiles (id) on delete set null,
  handled_at     timestamptz,
  created_at     timestamptz not null default now()
);

create index complaints_status_idx on complaints (status, created_at);


-- ---------------------------------------------------------------------------
-- Notifications and audit log (C-08, FR-10.2)
-- ---------------------------------------------------------------------------

-- The text is not stored. The page builds it from type and params with i18n.
create table notifications (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references profiles (id) on delete cascade,
  type       text not null
               check (type in ('booking_requested', 'booking_confirmed', 'booking_rejected',
                               'booking_cancelled', 'booking_rescheduled', 'booking_assigned',
                               'confirm_request', 'slot_released', 'payment_received',
                               'refund_issued', 'queue_turn_near', 'queue_wait_changed',
                               'review_received')),
  params     jsonb not null default '{}'::jsonb,
  booking_id uuid references bookings (id) on delete set null,
  is_read    boolean not null default false,
  created_at timestamptz not null default now()
);

create index notifications_user_idx on notifications (user_id, is_read, created_at desc);

create table audit_logs (
  id          uuid primary key default gen_random_uuid(),
  actor_id    uuid references profiles (id) on delete set null,
  action      text not null,
  entity_type text not null,
  entity_id   uuid,
  details     jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);

create index audit_logs_entity_idx on audit_logs (entity_type, entity_id, created_at desc);

-- The audit log is append only.
create function audit_logs_block_change() returns trigger
language plpgsql as $$
begin
  raise exception 'audit_logs rows cannot be changed or deleted';
end;
$$;

create trigger audit_logs_no_update_delete
  before update or delete on audit_logs
  for each row execute function audit_logs_block_change();


-- ---------------------------------------------------------------------------
-- Row level security
-- ---------------------------------------------------------------------------

-- Every table below is used only by the FastAPI backend, which connects with its
-- own database role. RLS is on and there are no policies, so the Supabase Data API
-- cannot read or write them. (public.profiles has its own policies in its migration.)
do $$
declare
  t text;
begin
  foreach t in array array[
    'commission_plans', 'shops', 'shop_working_hours', 'shop_documents', 'shop_images',
    'services', 'service_images', 'offers', 'offer_services',
    'staff', 'staff_services', 'staff_hours', 'staff_breaks', 'staff_time_off',
    'bookings', 'booking_items', 'payments', 'refunds',
    'queue_entries', 'queue_entry_services',
    'reviews', 'review_reports', 'complaints', 'notifications', 'audit_logs'
  ]
  loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end;
$$;
